	for offset, incoming := range request.Entries {
		idx := start + 1 + offset
		if idx > len(s.log) {
			break
		}
		if s.log[idx-1].Term != incoming.Term {
			cutAt = idx - 1 // 切片下标
			break
		}
	}
	if cutAt > 0 {
		s.log = append([]LogEntry(nil), s.log[:cutAt]...)
	}
	existingCount := len(s.log) - start
	if existingCount < 0 {
