	// 不删除；仅在存在任期冲突时截断，并追加冲突位置起的请求条目。
	prefixMatched := len(request.Entries)
	if cutAt >= 0 {
		prefixMatched = cutAt - start
		s.log = append([]LogEntry(nil), s.log[:cutAt]...)
	}
	if prefixMatched < len(request.Entries) {
		s.log = append(s.log, request.Entries[prefixMatched:]...)
	}

